INSERT INTO trechos (id, texto, publico, macronarrativa, pauta, tipo, forca, link, pagina) VALUES ('D12-TR-020', 'A narrativa central de Brasil Core vai do desencanto com o país real ao reencantamento lúcido com um Brasil possível.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '8'), ('D12-TR-021', 'A transformação semiótica vai da disjunção com um Brasil visto como problema, disputa ou propaganda para a conjunção com um orgulho maduro: amar o país apesar das falhas, reconhecendo nele potência coletiva, pertencimento e futuro possível.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '8'), ('D12-TR-175', 'Entre os participantes deste estudo, Brasil Core é a macronarrativa mais transversal: mesmo entre descrentes, o orgulho pelo país permanece como vínculo afetivo.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '30'), ('D12-TR-176', 'Nas redes, o orgulho nacional aparece como território disputado por campos políticos distintos, articulado a diplomacia, patriotismo e defesa de valores.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '30'), ('D12-TR-179', 'A força das mulheres e do povo brasileiro mobiliza, mas não pode romantizar sobrecarga.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'gênero e trabalho', 'achado', 'indício', NULL, '30'), ('D12-TR-182', 'O orgulho nacional convive com críticas a violência, serviços públicos, custo de vida e descrença institucional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '30'), ('D12-TR-183', 'A escuta digital mostra um patriotismo lúcido: amar o país apesar das falhas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '30'), ('D12-TR-185', 'O vínculo mais seguro com o país nasce da vida concreta: família, trabalho, cultura, comida, cuidado e orgulho regional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '30'), ('D12-TR-186', 'Nas redes, o amor pelo país aparece em cenas do dia a dia, laços familiares, estados, humor e experiências compartilhadas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '30'), ('D12-TR-189', 'Isotopia de país em disputa: o orgulho nacional é mobilizado por campos políticos diferentes e pode ser capturado pela polarização.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '32'), ('D12-TR-190', 'Os temas associados são patriotismo, soberania, diplomacia, liderança internacional, defesa de valores e pertencimento político.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'país em disputa', 'achado', 'indício', NULL, '32'), ('D12-TR-192', 'Isotopia de potência brasileira: o país gera orgulho quando aparece como capacidade coletiva, criatividade e reconhecimento.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '32'), ('D12-TR-193', 'Os temas associados são esporte, cultura, ciência, cinema, saúde pública, tecnologia nacional e reconhecimento internacional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '32'), ('D12-TR-195', 'Isotopia do Brasil do cotidiano: o amor pelo país nasce de experiências concretas, próximas e afetivas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '32'), ('D12-TR-196', 'Os temas associados são família, trabalho, comida, humor, amigos, cuidado, território e orgulho regional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '32'), ('D12-TR-198', 'Isotopia de amor apesar das falhas: o vínculo com o Brasil se fortalece quando reconhece problemas sem abandonar o pertencimento.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '32'), ('D12-TR-199', 'Os temas associados são patriotismo lúcido e crítica à violência, à corrupção, à desigualdade e a serviços públicos falhos, sem negar orgulho e afeto.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '32'), ('D12-TR-203', 'A tensão central não é entre orgulho e vergonha do Brasil, mas entre desencanto com o país real e a possibilidade de se reencantar sem mentir.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '33'), ('D12-TR-204', 'O Brasil aparece atravessado por falhas concretas: violência, corrupção, desigualdade, serviços públicos insuficientes, custo de vida e descrença institucional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '33'), ('D12-TR-206', 'Busca-se uma forma crível de pertencimento: poder amar o Brasil sem negar seus problemas, reconhecer potência no país vivido e acreditar que algo ainda pode melhorar.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '33'), ('D12-TR-207', 'O Brasil volta a encantar quando aparece como experiência concreta e compartilhada: povo, cultura, comida, humor, família, SUS, PIX, ciência, esporte, território, acolhimento e reconhecimento internacional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '33'), ('D12-TR-209', 'O Brasil deixa de ser apenas problema, disputa ou propaganda e passa a aparecer como uma experiência comum, afetiva e reconhecível.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '33'), ('D12-TR-210', 'No estado final, há conjunção com um orgulho nacional mais maduro: é possível amar o Brasil apesar das falhas e se projetar em um país que ainda pode melhorar.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '34'), ('D12-TR-211', 'O reencantamento não apaga o desencanto, mas o reorganiza em esperança possível.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '34'), ('D12-TR-212', 'O território "O Brasil real que a gente ama" é transversal e parte do sentimento atual de amor pelo país apesar das falhas, ancorado em cotidiano, família, comida, humor, cuidado, trabalho e território.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '35'), ('D12-TR-214', 'O território "Potências que fazem acreditar" é transversal e reencanta ao mostrar capacidades reconhecíveis do país: SUS, PIX, ciência, esporte, cinema, cultura, mascotes e reconhecimento internacional.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '35'), ('D12-TR-216', 'O território "Pertencimento regional, orgulho nacional" é forte para o Nordeste e para identidades territoriais, e apresenta o país como soma de muitos Brasis: sotaques, estados, comidas, festas, paisagens e formas de viver.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '35'), ('D12-TR-218', 'O território "Futuro possível, não país perfeito" é transversal, especialmente para descrentes e indecisas, e organiza o orgulho como esperança concreta, não como propaganda ou negação das falhas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '35'), ('D12-TR-220', 'Os territórios partem do sentimento atual pelo Brasil real, reconhecendo falhas sem romper o vínculo afetivo, e chegam à ideia de um futuro possível, em que o país não precisa ser perfeito para voltar a mobilizar esperança.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '35'), ('D12-TR-221', 'O amor pelo Brasil nasce do país vivido: família, comida, humor, cuidado, trabalho e território, mesmo com falhas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'brasil cotidiano', 'achado', 'indício', NULL, '36'), ('D12-TR-222', 'A mulher aparece como sujeito que reconhece as dificuldades, mas preserva vínculo afetivo com o país.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '36'), ('D12-TR-224', 'O Brasil aparece como problema, disputa ou decepção.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '36'), ('D12-TR-226', 'No estado final, é possível amar o Brasil sem fingir que ele é perfeito.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '36'), ('D12-TR-227', 'O orgulho se reacende quando o país mostra capacidades concretas e reconhecíveis.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '37'), ('D12-TR-228', 'A mulher aparece como cidadã que se reconhece em conquistas coletivas que também fazem parte da sua vida.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'potências do país', 'achado', 'indício', NULL, '37'), ('D12-TR-232', 'No estado final, o Brasil volta a parecer potente, reconhecível e digno de orgulho.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'indício', NULL, '37'), ('D12-TR-233', 'O Brasil ganha força quando aparece como soma de muitos Brasis.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-234', 'A mulher aparece como sujeito de território: reconhece-se no sotaque, na comida, na cultura, nas festas e no modo de viver de onde vem.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-238', 'No estado final, amar o Brasil passa por se reconhecer no próprio território.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'pertencimento regional', 'achado', 'indício', NULL, '38'), ('D12-TR-239', 'Reencantar não é negar problemas, mas mostrar que ainda há potência para melhorar.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D12-TR-240', 'A mulher aparece como sujeito de esperança lúcida: critica o presente, mas pode se projetar em um país possível.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D12-TR-242', 'O desencanto faz o Brasil parecer travado ou perdido.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'confiança nas instituições', 'achado', 'indício', NULL, '39'), ('D12-TR-244', 'No estado final, o país não precisa ser perfeito para voltar a mobilizar esperança.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'futuro possível', 'achado', 'indício', NULL, '39'), ('D13-TR-119', 'Entre os participantes deste estudo, o orgulho pelo país é a macronarrativa mais transversal, atravessando inclusive o público mais cético e as mais desengajadas.', 'mulheres de 2 a 5 salários mínimos', 'brasil e pertencimento', 'orgulho e identidade nacional', 'achado', 'forte', NULL, NULL), ('D1